from collections import deque
def solve(events):
    lots, held, value, trades, out, realized = {}, {}, {}, {}, [], 0
    for e in events:
        kind, item = e[0], e[1]
        if kind == 'buy':
            q, p = e[2], e[3]
            lots.setdefault(item, deque()).append([q, p])
            held[item] = held.get(item, 0) + q; value[item] = value.get(item, 0) + q * p
            trades[item] = trades.get(item, 0) + 1
        elif kind == 'sell':
            trades[item] = trades.get(item, 0) + 1
            book, qty, price = lots.get(item), e[2], e[3]
            if not book: continue
            while qty and book:
                lot = book[0]; take = lot[0] if lot[0] < qty else qty
                realized += take * (price - lot[1]); lot[0] -= take; qty -= take
                held[item] -= take; value[item] -= take * lot[1]
                if not lot[0]: book.popleft()
        else:
            out.append([held.get(item, 0), value.get(item, 0), trades.get(item, 0), realized])
    return out

