import heapq
def solve(task):
    n = task['n']; adj = [dict() for _ in range(n)]
    for u, v, w in task['edges']:
        if w >= 0: adj[u][v] = w
    cache, out = {}, []
    for op in task['ops']:
        if op[0] == 'set':
            u, v, w = op[1], op[2], op[3]
            if w >= 0: adj[u][v] = w
            else: adj[u].pop(v, None)
            cache.clear(); continue
        s, t = op[1], op[2]
        dist = cache.get(s)
        if dist is None:
            dist = {s: 0}; heap = [(0, s)]; done = set()
            while heap:
                d, u = heapq.heappop(heap)
                if u in done: continue
                done.add(u)
                for v, w in adj[u].items():
                    nd = d + w
                    if nd < dist.get(v, 1 << 62): dist[v] = nd; heapq.heappush(heap, (nd, v))
            cache[s] = dist
        out.append(dist.get(t, -1))
    return out
